{
  "scenario_title": "Annual household listed share and investment fund ownership rates across UK regions by income quintile, 2016–2023",
  "data_context": "The Office for National Statistics (ONS), in collaboration with financial regulatory authorities, published recurring estimates from the Wealth and Assets Survey between 2016 and 2023. The dataset tracks retail participation rates in listed equities and pooled investment funds, alongside per capita holding amounts across territorial regions and household income quintiles, to evaluate regional wealth inequality and capital market participation trends.",
  "script": "dim(\"region\", [\"London\", \"South East\", \"North West\", \"West Midlands\", \"Scotland\", \"Wales and South West\"], weights=[0.22, 0.20, 0.16, 0.15, 0.14, 0.13], group=\"geography\")\ndim(\"income_quintile\", [\"Quintile 1 (Lowest)\", \"Quintile 2\", \"Quintile 3\", \"Quintile 4\", \"Quintile 5 (Highest)\"], weights=[0.20, 0.20, 0.20, 0.20, 0.20], ordered=\"ordinal\", group=\"socioeconomic\")\ndim(\"holding_type\", [\"Direct Listed Shares\", \"Pooled Investment Funds\"], weights=[0.55, 0.45], group=\"portfolio\")\n\ntime(\"survey_period\", start=\"2016-01-01\", end=\"2023-12-31\", freq=\"monthly\")\n\nmeasure(\"ownership_rate\",\n        \"clip({\\\"Quintile 1 (Lowest)\\\": 4.0, \\\"Quintile 2\\\": 9.0, \\\"Quintile 3\\\": 16.0, \\\"Quintile 4\\\": 26.0, \\\"Quintile 5 (Highest)\\\": 42.0}[income_quintile] + {\\\"London\\\": 6.5, \\\"South East\\\": 4.0, \\\"North West\\\": -1.5, \\\"West Midlands\\\": -2.0, \\\"Scotland\\\": -1.0, \\\"Wales and South West\\\": -2.5}[region] + [holding_type=Pooled Investment Funds] * 2.5 + survey_period * 0.0012 + gaussian(0, 1.2), 0.5, 65.0)\",\n        unit=\"% of households\", additive=False)\n\nmeasure(\"annual_change_ppt\",\n        \"clip(gaussian(0.4, 0.8) + [income_quintile=Quintile 5 (Highest)] * 0.5 + [region=London] * 0.3, -5.0, 8.0)\",\n        unit=\"percentage points\", additive=False)\n\nmeasure(\"per_capita_holdings\",\n        \"lognormal(mu = 7.0 + {\\\"Quintile 1 (Lowest)\\\": 0.0, \\\"Quintile 2\\\": 0.6, \\\"Quintile 3\\\": 1.2, \\\"Quintile 4\\\": 1.9, \\\"Quintile 5 (Highest)\\\": 2.8}[income_quintile] + {\\\"London\\\": 0.45, \\\"South East\\\": 0.30, \\\"North West\\\": -0.15, \\\"West Midlands\\\": -0.20, \\\"Scotland\\\": -0.10, \\\"Wales and South West\\\": -0.15}[region] + [holding_type=Pooled Investment Funds] * 0.25, sigma = 0.35)\",\n        unit=\"GBP\", additive=True)\n\nemit(360)",
  "intents": [
    {
      "sentence": "How listed share ownership rates vary across UK regions and income quintiles",
      "columns": [
        "region",
        "income_quintile",
        "ownership_rate"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "Trend in household equity and investment fund participation rates from 2016 through 2023",
      "columns": [
        "survey_period",
        "ownership_rate"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Relationship between household ownership rate and per capita holdings value",
      "columns": [
        "ownership_rate",
        "per_capita_holdings"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
